}

#include <stdio.h>
int main(void) {
    int n = 3, refl = 0, sym = 0, both = 0;
    for (int m = 0; m < (1 << (n * n)); m++) {
        int r = 1, s = 1;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                int in = (m >> (i * n + j)) & 1;
                int back = (m >> (j * n + i)) & 1;
                if (i == j && !in) r = 0;
                if (in != back) s = 0;
            }
        refl += r; sym += s; both += r && s;
    }
    printf("%d %d %d\n", refl, sym, both);
    return 0;
}

