int p[9];
int find(int x) {
    int r = x;
    while (p[r] > 0) r = p[r];
    while (x != r) { int next = p[x]; p[x] = r; x = next; }
    return r;
}
void unite(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return;
    if (p[ra] <= p[rb]) { p[ra] += p[rb]; p[rb] = ra; }
    else { p[rb] += p[ra]; p[ra] = rb; }
}
